const text = String($json.text || '');
const ocrUsado = Boolean($json.ocrUsado);
const query = $('Receber PDF').first().json.query || {};
const expectedProvider = String(query.provedorEsperado || '').trim();
const expectedNormalized = expectedProvider.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const digits = (value) => String(value || '').replace(/\D/g, '');
const cnpjMatches = text.match(/(?:\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/g) || [];
const cnpjCandidatos = [...new Set(cnpjMatches.map((value) => digits(value)).filter((value) => value.length === 14))];
const dateValue = (value) => {
  if (!value) return '';
  const match = value.match(/(\d{2})[\/.\-](\d{2})[\/.\-](\d{4})|(\d{4})-(\d{2})-(\d{2})/);
  if (!match) return '';
  return match[4] ? `${match[4]}-${match[5]}-${match[6]}` : `${match[3]}-${match[2]}-${match[1]}`;
};
const afterLabel = (pattern) => {
  const match = text.match(pattern);
  return match ? match[1] : '';
};
const vencimentoRaw = afterLabel(/(?:data\s+de\s+)?vencimento\s*[:\-]?\s*(\d{2}[\/.\-]\d{2}[\/.\-]\d{4}|\d{4}-\d{2}-\d{2})/i);
const amountRaw = afterLabel(/(?:valor\s+total\s+(?:da\s+)?(?:fatura|conta)|total\s+(?:da\s+)?(?:fatura|conta)|total\s+a\s+pagar|valor\s+a\s+pagar)[^\d]{0,50}(?:R\$\s*)?([\d.]+,\d{2})/i);
const parseAmount = (value) => {
  if (!value) return null;
  const parsed = Number(value.replace(/\./g, '').replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
};
const lines = text.split(/\r?\n/);
const issuerPattern = /telecom|telecomunic|provedor|internet|comunicacoes|telefonia/i;
const issuerCandidates = lines.filter((line) => issuerPattern.test(line));
const expectedLine = expectedNormalized ? issuerCandidates.find((line) => line.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().includes(expectedNormalized)) || '' : '';
const expectedFound = Boolean(expectedLine);
const issuerLine = expectedLine || issuerCandidates[0] || '';
const issuerCnpj = cnpjMatches.find((cnpj) => {
  const index = text.indexOf(cnpj);
  const context = text.slice(Math.max(0, index - 120), index + cnpj.length + 120).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  return /telecom|telecomunic|provedor|internet|comunicacoes/i.test(context);
});
const serviceDescription = (() => {
  const tableHeader = /itens?\s+de\s+servi[cç]os?/i;
  const tableRow = /^\s*\S+\s+\d+(?:[.,]\d+)?\s+(.+?)\s{2,}(?=R\$|[\d.]+,\d{2}|\d+[.,]\d{2})/i;
  for (let index = 0; index < lines.length; index += 1) {
    if (!tableHeader.test(lines[index])) continue;
    for (const line of lines.slice(index + 1, index + 8)) {
      const match = line.match(tableRow);
      if (match) return match[1].trim().slice(0, 1000);
    }
  }
  const serviceLabel = /(?:descri[cç][aã]o\s+(?:do\s+)?servi[cç]o|discrimina[cç][aã]o\s+dos?\s+servi[cç]os|servi[cç]os?\s+prestados?|item\s+de\s+cobran[cç]a|servi[cç]o\s*[-–—]\s*discrimina[cç][aã]o)/i;
  const nonServiceLine = /^(?:valor|total|vencimento|emiss[aã]o|compet[eê]ncia|per[ií]odo|quantidade|unidade|c[oó]digo|subtotal|imposto|tributos|base de c[aá]lculo)\b/i;
  for (let index = 0; index < lines.length; index += 1) {
    if (!serviceLabel.test(lines[index])) continue;
    const sameLine = lines[index].replace(serviceLabel, '').replace(/^[\s:—–-]+/, '').trim();
    const nextLine = lines.slice(index + 1).map((line) => line.trim()).find((line) => line && !nonServiceLine.test(line)) || '';
    const candidate = sameLine || nextLine;
    if (candidate && !nonServiceLine.test(candidate)) return candidate.slice(0, 1000);
  }
  return '';
})();
const invoiceNumber = afterLabel(/(?:n[uú]mero|n[uú]m\.?|n[oº]\.?)\s*[:º-]*(?:da\s+)?(?:fatura|conta)\s*[:#-]?\s*([A-Z0-9./-]+)/i)
  || afterLabel(/(?:fatura|conta)\s*(?:n[uú]mero|n[uú]m\.?|n[oº]\.?)\s*[:º-]*([A-Z0-9./-]+)/i);
const issuedRaw = afterLabel(/(?:data\s+de\s+)?(?:emiss[aã]o|emitida\s+em)\s*[:\-]?\s*(\d{2}[\/.\-]\d{2}[\/.\-]\d{4}|\d{4}-\d{2}-\d{2})/i);
const expectedAmount = Number(query.valorEsperado || 0);
const valorTotal = parseAmount(amountRaw);
return {
  json: {
    ok: true,
    textEncontrado: text.trim().length > 0,
    ocrUsado,
    emissorNome: issuerLine.trim(),
    emissorEsperadoEncontrado: expectedFound,
    cnpjEmissor: issuerCnpj ? digits(issuerCnpj) : (cnpjCandidatos.length === 1 ? cnpjCandidatos[0] : ''),
    cnpjCandidatos,
    numeroFatura: invoiceNumber,
    dataEmissao: dateValue(issuedRaw),
    dataVencimento: dateValue(vencimentoRaw),
    valorTotal,
    descricaoServico: serviceDescription,
    comparacao: {
      emissorConfere: expectedFound,
      valorConfere: expectedAmount > 0 && valorTotal !== null && Math.abs(expectedAmount - valorTotal) < 0.01,
      vencimentoConfere: !query.vencimentoEsperado || query.vencimentoEsperado === dateValue(vencimentoRaw)
    },
    camposParaRevisar: ['emissorNome', 'cnpjEmissor', 'numeroFatura', 'dataEmissao', 'dataVencimento', 'valorTotal', 'descricaoServico'],
    aviso: text.trim() ? '' : 'Nenhum texto foi reconhecido no PDF, mesmo após o OCR local; confira os campos manualmente.'
  }
};
